config.script:
try:
	tipId = self.view.params.tipId
	tipText = self.view.params.tipText
	tipTitle = self.view.params.tipTitle
	pulseColor = self.view.params.pulseColor
	system.perspective.sendMessage('debug-log', {'source': 'TipBadge', 'message': 'Dot clicked: ' + tipId}, scope='session')
	params = {'tipId': tipId, 'tipText': tipText, 'tipTitle': tipTitle, 'pulseColor': pulseColor}
	style = {'modal': False, 'draggable': False, 'resizable': False, 'showCloseIcon': False, 'viewportBound': True}
	system.perspective.openPopup('TipPopup_' + tipId, 'Components/Workmate/Objects/Symbols/TipPopup', params, '', style)
except Exception as e:
	system.perspective.sendMessage('debug-log', {'source': 'TipBadge', 'message': 'onClick ERROR: ' + str(e)}, scope='session')
